mapper.select:
select id, mix_area, schedule_date, glue, shelf_num1, shelf_num2, remark, del_flag, create_by, create_time, update_by, update_time from t_glue_unclaimed
where del_flag = '0'
and mix_area = #{mixArea}
and schedule_date = #{scheduleDate}
and glue = #{glue}

    order by create_time desc


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.scheduleDate} schedule_date, #{data.mixArea} mix_area, #{data.glue} glue,
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_unclaimed m inner join temp_table t on m.schedule_date = t.schedule_date and m.mix_area = t.mix_area and m.glue = t.glue and m.del_flag ='0'

